    [DllImport("kernel32.dll",CharSet=CharSet.Unicode,SetLastError=true)]static extern bool MoveFileW(string source,string target);
    static byte[] Pack(string body="Retained complete snapshot bytes"){using var output=new MemoryStream();using(var zip=new ZipArchive(output,ZipArchiveMode.Create,true)){using(var w=new StreamWriter(zip.CreateEntry("text.md").Open()))w.Write("---\ntextTextId: folder-propagation-item\n---\n"+body);using(var w=new BinaryWriter(zip.CreateEntry("assets/exact.bin").Open()))w.Write(new byte[]{0,255,19,72});}return output.ToArray();}
    static SyncEngine.State State(TextPackStore s)=>JsonSerializer.Deserialize<SyncEngine.State>(File.ReadAllBytes(Path.Combine(s.StateDirectory,"sync.json")))!;
    static void Floor(TextPackStore store,Action<string>? hook=null)=>typeof(RetainedReplacementProfile).GetMethod("PrepareFolderSync",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Static)!.Invoke(null,[store,hook]);
    sealed class Handler(Func<HttpRequestMessage,Task<HttpResponseMessage>> send):HttpMessageHandler{protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage r,CancellationToken ct)=>send(r);}
    public static async Task Run(string temp,Action<bool,string> check)
    {
        foreach(var boundary in new[]{"folderSyncProfilePreserved","folderSyncProfileStaged","beforeFolderSyncProfilePublication","folderSyncProfilePublished"}){
            var owned=new TextPackStore(Path.Combine(temp,boundary),Path.Combine(temp,boundary+"-state"));AccountRootOwnership.Open(owned,new Uri("https://texttext.test"),"folder-workspace","folder-account");var failed=false;try{Floor(owned,p=>{if(p==boundary)throw new IOException("Injected profile floor interruption");});}catch(System.Reflection.TargetInvocationException e)when(e.InnerException is IOException){failed=true;}Floor(owned);var dir=Path.Combine(owned.StateDirectory,"retained-replacement-profile");var marker=JsonSerializer.Deserialize<RetainedReplacementProfile.Marker>(File.ReadAllBytes(Path.Combine(dir,"profile.json")))!;check(failed&&marker.Version==3&&File.ReadAllBytes(Path.Combine(dir,"profile-v2.json")).SequenceEqual(File.ReadAllBytes(Path.Combine(dir,"profile-v2-displaced.json"))),"folder sync profile interruption resumes with exact prior bytes "+boundary);
        }
        var wireCalls=0;var operation=Guid.NewGuid().ToString("D");var wire=new FolderCaseMoveRequest(operation,"Notes","notes",new string('a',64),["Notes","Notes/Empty child"],[]);
        using(var client=new HttpClient(new Handler(async request=>{wireCalls++;if(wireCalls==1)return new System.Net.Http.HttpResponseMessage(System.Net.HttpStatusCode.OK){Content=new StringContent(JsonSerializer.Serialize(new{items=Array.Empty<object>(),folders=new[]{"Notes","Notes/Empty child"},fullAccess=true,canCreateContent=true,manifestRevision=new string('a',64),syncCapabilities=new[]{"folder-case-moves-v1"}}))};var json=JsonDocument.Parse(await request.Content!.ReadAsStringAsync());check(request.RequestUri!.AbsolutePath=="/api/vault/items/folder-case-moves"&&request.Headers.GetValues("X-TextText-Account").Single()=="folder-account"&&json.RootElement.GetProperty("operationId").GetString()==operation&&json.RootElement.GetProperty("folders").GetArrayLength()==2,"HTTP folder command uses exact capability endpoint, account binding and lowercase wire fields");return new(System.Net.HttpStatusCode.OK){Content=new StringContent(JsonSerializer.Serialize(new FolderCaseMoveReceipt(operation,"moved","Notes","notes",["notes","notes/Empty child"],[],new string('b',64)),new JsonSerializerOptions{PropertyNamingPolicy=JsonNamingPolicy.CamelCase}))};}))) {
            var transport=new HttpSyncTransport(client,new("https://texttext.test"),"items","folder-account",()=>Task.FromResult(new SyncAccountCredential("fixture-token","folder-account")));await transport.ManifestAsync();check(transport.SupportsFolderCaseMoves&&transport.ManifestRevision==new string('a',64),"HTTP folder capability uses explicit authenticated raw manifest revision");var reply=await transport.MoveFolderCaseAsync(wire);check(reply.OperationId==operation&&reply.Folders.Contains("notes/Empty child"),"HTTP folder reply decodes complete retained subtree");
        }

        if(!OperatingSystem.IsWindows()){Console.WriteLine("SKIP folder propagation physical directory identity requires actual Windows.");return;}
        foreach(var empty in new[]{false,true})foreach(var shared in new[]{false,true})foreach(var failure in new[]{"normal","lost-ack","committed409"}){
            var lost=failure!="normal";
            if(empty&&shared)continue;
            var label=(empty?"empty":shared?"shared":"pack")+"-"+failure;var store=new TextPackStore(Path.Combine(temp,label),Path.Combine(temp,label+"-state"));AccountRootOwnership.Open(store,new Uri("https://texttext.test"),"folder-workspace","folder-account");var bytes=Pack();store.EnsureFolders(["Notes/Empty child"]);PackFile? file=empty?null:store.Write("Notes/CaseProbe.textpack",bytes);
            var remote=new Test.Fake{SupportsFolderCaseMoves=true,ManifestRevision=new string('a',64),Folders=["Notes","Notes/Empty child"],AuthoritativeFolders=["Notes","Notes/Empty child"],Data=bytes,Item=file is null?null:new(file.ItemId,file.Path,file.Hash)};
            var attempts=new List<FolderCaseMoveRequest>();FolderCaseMoveReceipt? committed=null;var fail=lost;
            remote.FolderMove=request=>{attempts.Add(request);if(committed is null){if(request.Source!="Notes"||request.Destination!="notes"||!request.Folders.SequenceEqual(new[]{"Notes","Notes/Empty child"})||request.BaseManifestRevision!=new string('a',64))throw new Exception("Incorrect folder topology CAS.");remote.Folders=remote.AuthoritativeFolders=["notes","notes/Empty child"];if(remote.Item is {} item)remote.Item=item with{RelativePath="notes/CaseProbe.textpack"};remote.ManifestRevision=new string('b',64);committed=new(request.OperationId,"moved",request.Source,request.Destination,["notes","notes/Empty child"],request.Items.Select(x=>x with{RelativePath="notes"+x.RelativePath[5..]}).ToArray(),remote.ManifestRevision);}if(fail){fail=false;if(failure=="committed409")throw new SyncConflictException();throw new HttpRequestException("Lost committed folder receipt");}return Task.FromResult(committed);};
            await Test.NewSync(store,remote).SyncAsync();var baseline=State(store).FolderBaseline;check(baseline is not null&&baseline.Identities.Length==2&&baseline.Folders.Contains("Notes/Empty child"),label+" retains authenticated complete folder topology and physical identities");
            SharedCheckpoint? checkpoint=null;
            if(shared){var journal=JsonSerializer.Serialize(new{version=1,epoch=3,seq=11,journalGeneration=7,revision=file!.Hash,relativePath=file.Path,update="AAA=",pending=new[]{"AAA="},batch=new{operationId="retained-folder-operation",updates=new[]{"AAA="}}});checkpoint=new SharedCheckpoint(file!.ItemId,file.Path,file.Hash,file.Hash,3,11,7,journal,true);var directory=Path.Combine(store.StateDirectory,"shared-editing",file.ItemId);Directory.CreateDirectory(directory);TextPackStore.AtomicWrite(Path.Combine(directory,"checkpoint.json"),JsonSerializer.SerializeToUtf8Bytes(checkpoint));}
            if(!MoveFileW(store.Resolve("Notes"),store.Resolve("notes")))throw new IOException("Fixture ordinary directory rename failed: "+Marshal.GetLastWin32Error());
            if(lost){var refused=false;try{await Test.NewSync(store,remote).SyncAsync();}catch(Exception e)when(e is HttpRequestException or SyncConflictException){refused=true;}var pending=State(store).FolderCommand;check(refused&&pending is not null&&remote.UploadCount==0,label+" lost reply retains exact folder command before any child upload");}
            await Test.NewSync(store,remote).SyncAsync();var final=State(store);check(final.FolderCommand is null&&attempts.Count==(lost?2:1)&&attempts.All(x=>JsonSerializer.Serialize(x)==JsonSerializer.Serialize(attempts[0]))&&final.ManagedFolders!.SequenceEqual(new[]{"notes","notes/Empty child"}),label+" receipt replay preserves operation identity and complete empty subtree");
            check(Directory.Exists(store.Resolve("notes/Empty child"))&&(empty||store.Read("notes/CaseProbe.textpack").SequenceEqual(bytes))&&remote.UploadCount==0,label+" folder receipt preserves exact pack/assets and avoids per-item upload");
            if(checkpoint is not null){var cp=JsonSerializer.Deserialize<SharedCheckpoint>(File.ReadAllBytes(Path.Combine(store.StateDirectory,"shared-editing",checkpoint.ItemId,"checkpoint.json")))!;var expected=JsonNode.Parse(checkpoint.Journal)!;expected["relativePath"]="notes/CaseProbe.textpack";check(cp.Path=="notes/CaseProbe.textpack"&&cp.Epoch==checkpoint.Epoch&&cp.Seq==checkpoint.Seq&&cp.JournalGeneration==checkpoint.JournalGeneration&&JsonNode.DeepEquals(expected,JsonNode.Parse(cp.Journal)),label+" receipt rebases pending shared path without changing batch/epoch/sequence/generation");}
            var profile=Path.Combine(store.StateDirectory,"retained-replacement-profile");var marker=JsonSerializer.Deserialize<RetainedReplacementProfile.Marker>(File.ReadAllBytes(Path.Combine(profile,"profile.json")))!;check(marker.Version==3&&File.ReadAllBytes(Path.Combine(profile,"profile-v2.json")).SequenceEqual(File.ReadAllBytes(Path.Combine(profile,"profile-v2-displaced.json"))),label+" floor three retains exact previous profile before folder outbox");
        }
        {
            var store=new TextPackStore(Path.Combine(temp,"fresh-content"),Path.Combine(temp,"fresh-content-state"));AccountRootOwnership.Open(store,new Uri("https://texttext.test"),"folder-workspace","folder-account");store.EnsureFolders(["Notes/Empty child"]);var original=Pack();var file=store.Write("Notes/CaseProbe.textpack",original);var remote=new Test.Fake{SupportsFolderCaseMoves=true,ManifestRevision=new string('a',64),Folders=["Notes","Notes/Empty child"],AuthoritativeFolders=["Notes","Notes/Empty child"],Data=original,Item=new(file.ItemId,file.Path,file.Hash)};await Test.NewSync(store,remote).SyncAsync();var latest=Pack("Ordinary remote text before folder intent");var freshRevision=TextPackStore.Hash(latest);remote.Data=latest;remote.Item=remote.Item with{Revision=freshRevision};remote.ManifestRevision=new string('c',64);var calls=0;remote.FolderMove=r=>{calls++;check(r.BaseManifestRevision==new string('c',64)&&r.Items.Single().Revision==freshRevision,"folder intent uses fresh content revision while retaining original topology");remote.Item=remote.Item with{RelativePath="notes/CaseProbe.textpack"};remote.Folders=remote.AuthoritativeFolders=["notes","notes/Empty child"];remote.ManifestRevision=new string('d',64);return Task.FromResult(new FolderCaseMoveReceipt(r.OperationId,"moved",r.Source,r.Destination,["notes","notes/Empty child"],r.Items.Select(i=>i with{RelativePath="notes/CaseProbe.textpack"}).ToArray(),remote.ManifestRevision));};if(!MoveFileW(store.Resolve("Notes"),store.Resolve("notes")))throw new IOException("Fixture rename failed.");await Test.NewSync(store,remote).SyncAsync();check(calls==1&&store.Read("notes/CaseProbe.textpack").SequenceEqual(latest)&&remote.UploadCount==0,"folder receipt preserves independent content hash baseline and pulls ordinary remote text");
        }
        foreach(var mode in new[]{"capability","topology","foreign-identity","unknown-entry","wrong-receipt","changed-after-rpc","conflict","future-command","existing-upload"}){
            var store=new TextPackStore(Path.Combine(temp,"refusal-"+mode),Path.Combine(temp,"refusal-"+mode+"-state"));AccountRootOwnership.Open(store,new Uri("https://texttext.test"),"folder-workspace","folder-account");store.EnsureFolders(["Notes/Empty child"]);var remote=new Test.Fake{SupportsFolderCaseMoves=true,ManifestRevision=new string('a',64),Folders=["Notes","Notes/Empty child"],AuthoritativeFolders=["Notes","Notes/Empty child"]};if(mode=="existing-upload"){remote.Data=Pack();var f=store.Write("Notes/CaseProbe.textpack",remote.Data);remote.Item=new(f.ItemId,f.Path,f.Hash);}await Test.NewSync(store,remote).SyncAsync();if(mode=="existing-upload"){var state=State(store);state.Outbox.Add(new SyncEngine.Operation("retained-command","upload","folder-propagation-item","Notes/CaseProbe.textpack",null,null,new string('f',64),Convert.ToBase64String(Pack())));TextPackStore.AtomicWrite(Path.Combine(store.StateDirectory,"sync.json"),JsonSerializer.SerializeToUtf8Bytes(state));}var calls=0;remote.FolderMove=r=>{calls++;if(mode=="conflict")throw new SyncConflictException();if(mode=="future-command")throw new HttpRequestException("lost reply");if(mode=="changed-after-rpc")Directory.CreateDirectory(store.Resolve("notes/New child"));return Task.FromResult(new FolderCaseMoveReceipt(mode=="wrong-receipt"?Guid.NewGuid().ToString("D"):r.OperationId,"moved",r.Source,r.Destination,["notes","notes/Empty child"],[],new string('b',64)));};
            if(mode=="foreign-identity"){Directory.Move(store.Resolve("Notes"),store.Resolve("retained-original"));Directory.CreateDirectory(store.Resolve("notes"));}else if(!MoveFileW(store.Resolve("Notes"),store.Resolve("notes")))throw new IOException("Fixture rename failed.");
            if(mode=="capability")remote.SupportsFolderCaseMoves=false;if(mode=="topology"){remote.Folders=remote.AuthoritativeFolders=["Notes","Notes/Empty child","Unrelated new"];}if(mode=="unknown-entry")File.WriteAllText(store.Resolve("notes/unrecognized.bin"),"retained raw bytes");
            var refused=false;try{await Test.NewSync(store,remote).SyncAsync();}catch(Exception e)when(e is IOException or InvalidDataException or HttpRequestException){refused=true;}
            check(refused&&remote.UploadCount==0&&remote.DeleteCount==0&&calls==(mode is "wrong-receipt" or "changed-after-rpc" or "conflict" or "future-command"?1:0),"folder refusal preserves all trees and sends no child command: "+mode);
            if(mode=="future-command"){var statePath=Path.Combine(store.StateDirectory,"sync.json");var json=JsonNode.Parse(File.ReadAllText(statePath))!;json["FolderCommand"]!["FutureUnsupported"]=true;var exact=json.ToJsonString();TextPackStore.AtomicWrite(statePath,System.Text.Encoding.UTF8.GetBytes(exact));var rejected=false;try{await Test.NewSync(store,remote).SyncAsync();}catch(JsonException){rejected=true;}check(rejected&&calls==1&&File.ReadAllText(statePath)==exact,"future folder command fields refuse without replay or state rewrite");}
            if(mode=="conflict"){var exact=JsonSerializer.Serialize(State(store).FolderCommand);try{await Test.NewSync(store,remote).SyncAsync();}catch(IOException){}check(calls==2&&JsonSerializer.Serialize(State(store).FolderCommand)==exact,"HTTP409 retains immutable command and permits exact receipt replay");}
        }
        {
            var store=new TextPackStore(Path.Combine(temp,"policy-durable-race"),Path.Combine(temp,"policy-durable-race-state"));
            AccountRootOwnership.Open(store,new Uri("https://texttext.test"),"folder-workspace","folder-account");
            store.EnsureFolders(["Notes/Empty child"]);
            var remote=new Test.Fake{SupportsFolderCaseMoves=true,ManifestRevision=new string('a',64),Folders=["Notes","Notes/Empty child"],AuthoritativeFolders=["Notes","Notes/Empty child"]};
            await Test.NewSync(store,remote).SyncAsync();
            if(!MoveFileW(store.Resolve("Notes"),store.Resolve("notes")))throw new IOException("Fixture rename failed.");
            var calls=0;remote.FolderMove=_=>{calls++;throw new IOException("Must not dispatch");};
            byte[]? changed=null;
            var policy=NativePolicyTestHost.Create(beforeRequest:script=>{
                if(changed is null&&script.Contains(".folder(")) {
                    var value=System.Text.Json.Nodes.JsonNode.Parse(File.ReadAllBytes(Path.Combine(store.StateDirectory,"sync.json")))!;
                    value["policyRaceMarker"]="retained-external-state";
                    changed=System.Text.Encoding.UTF8.GetBytes(value.ToJsonString());
                    TextPackStore.AtomicWrite(Path.Combine(store.StateDirectory,"sync.json"),changed);
                }
                return Task.CompletedTask;
            });
            var refused=false;try{await new SyncEngine(store,remote,mirrorPolicy:policy).SyncAsync();}catch(IOException){refused=true;}
            check(refused&&changed is not null&&calls==0&&File.ReadAllBytes(Path.Combine(store.StateDirectory,"sync.json")).SequenceEqual(changed),"folder policy await refuses changed durable state without tail overwrite or dispatch");
            check(Directory.Exists(store.Resolve("notes/Empty child"))&&!Directory.EnumerateDirectories(store.Root).Select(Path.GetFileName).Contains("Notes",StringComparer.Ordinal),"folder policy refusal preserves exact moved empty tree");
        }

    }
